// Portrait (background removed) that the hero particles form; clear this string to fall back to the initials AP
const HERO_PORTRAIT='data:image/png;base64,';
// Show the loading mark first, then reveal the name.
(function(){
  var w=document.getElementById('pw'),t='AJITH KUMAR';
  t.split('').forEach(function(c,i){var s=document.createElement('span');s.textContent=c===' '?'\u00a0':c;s.style.animationDelay=(1.1+i*.07)+'s';w.appendChild(s)});
  setTimeout(function(){document.getElementById('pre').classList.add('done')},2900);
})();

// Build the hero portrait from particles and let the pointer gently disturb them.
(function(){
  var cv=document.getElementById('cv'),cx=cv.getContext('2d'),P=[],m={x:-999,y:-999},W,H,dpr=Math.min(devicePixelRatio||1,2);
  var im=null;if(HERO_PORTRAIT){im=new Image();im.onload=function(){build()};im.src=HERO_PORTRAIT}
  var still=matchMedia('(prefers-reduced-motion:reduce)').matches;
  function build(){
    W=cv.clientWidth;H=cv.clientHeight;cv.width=W*dpr;cv.height=H*dpr;cx.setTransform(dpr,0,0,dpr,0,0);
    var o=document.createElement('canvas');o.width=W;o.height=H;var o2=o.getContext('2d');
    var photo=im&&im.complete&&im.naturalWidth,step=W<600?4:3;
    if(photo){
      var ar=im.naturalWidth/im.naturalHeight,by=Math.max(H*.04,88),bh=Math.min(H*.74,W*.96/ar),bw=bh*ar,bx=(W-bw)/2;
      o2.drawImage(im,bx,by,bw,bh);
    }else{
      var fs=Math.min(H*.62,W*.5);o2.fillStyle='#fff';o2.font='900 '+fs+'px Montserrat,Arial,sans-serif';o2.textAlign='center';o2.textBaseline='middle';
      o2.fillText('AP',W/2,H*.38);
    }
    var d=o2.getImageData(0,0,W,H).data;P=[];
    for(var y=0;y<H;y+=step)for(var x=0;x<W;x+=step){
      var k=(y*W+x)*4,a=d[k+3];
      if(photo){
        var dk=1-d[k]/255,t=(y-by)/bh,fd=t<.68?1:Math.max(0,1-(t-.68)/.32);fd=fd*fd*(3-2*fd);
        if(a>110&&dk*fd>.07)P.push({x:Math.random()*W,y:Math.random()*H,tx:x,ty:y,r:(.5+dk*2.7)*(.4+.6*fd),c:'#000'});
      }else if(a>128)P.push({x:Math.random()*W,y:Math.random()*H,tx:x,ty:y,r:Math.random()*1.3+.5,c:Math.random()>.7?'#9fb4ff':'#d5d8e2'});
    }
  }
  function frame(){
    cx.clearRect(0,0,W,H);
    // scroll progress through the hero: 0 = image intact, 1 = fully dissolved; always reversible
    var s=Math.min(Math.max(scrollY/(H*.75),0),1);
    if(s<1){
      cx.globalAlpha=.92;
      for(var i=0;i<P.length;i++){
        var p=P[i];
        if(p.th===undefined){p.ox=p.oy=p.ou=p.ov=0;p.vx=(Math.random()-.5)*280;p.vy=-40-Math.random()*220;p.th=.2+Math.random()*.8}
        p.x+=(p.tx-p.x)*(still?1:.045);p.y+=(p.ty-p.y)*(still?1:.045);
        var bx=p.x+p.vx*s,by=p.y+p.vy*s;
        if(!still){
          var dx=m.x-bx,dy=m.y-by,dist=Math.sqrt(dx*dx+dy*dy);
          if(dist<100&&dist>.1){var f=(1-dist/100)*3.2;p.ou-=dx/dist*f;p.ov-=dy/dist*f}
          p.ou=(p.ou-p.ox*.09)*.84;p.ov=(p.ov-p.oy*.09)*.84;p.ox+=p.ou;p.oy+=p.ov;
        }
        if(s>p.th)continue;
        var z=p.r*(1-s*.6);
        cx.fillStyle=p.c;cx.fillRect(bx+p.ox,by+p.oy,z,z);
      }
    }
    requestAnimationFrame(frame);
  }
  var started=false;
  function go(){build();if(!started){started=true;frame()}}
  (document.fonts&&document.fonts.ready?document.fonts.ready:Promise.resolve()).then(go);
  addEventListener('resize',build);
  cv.parentNode.addEventListener('pointermove',function(e){if(e.pointerType==='touch')return;var r=cv.getBoundingClientRect();m.x=e.clientX-r.left;m.y=e.clientY-r.top});
  cv.parentNode.addEventListener('pointerleave',function(){m.x=m.y=-999});
})();

// Keep the services list to one expanded item at a time.
document.querySelectorAll('.row button').forEach(function(b){
  b.addEventListener('click',function(){
    var r=b.parentNode,open=r.classList.contains('open');
    document.querySelectorAll('.row.open').forEach(function(o){o.classList.remove('open');o.querySelector('button').setAttribute('aria-expanded','false')});
    if(!open){r.classList.add('open');b.setAttribute('aria-expanded','true')}
  });
});

// Highlight the navigation link for the section in view.
var links=document.querySelectorAll('nav a');
var io=new IntersectionObserver(function(es){es.forEach(function(e){
  if(e.isIntersecting){links.forEach(function(a){a.classList.toggle('on',a.getAttribute('href')==='#'+e.target.id)})}
})},{rootMargin:'-45% 0px -50% 0px'});
document.querySelectorAll('main section').forEach(function(s){io.observe(s)});

// Reveal the headline one character at a time after the preloader.
(function(){
  var b=document.querySelector('.big');b.setAttribute('aria-label','Portfolio');
  b.innerHTML=b.textContent.split('').map(function(c,i){return '<span aria-hidden="true" style="transition-delay:'+(i*.07)+'s">'+c+'</span>'}).join('');
  setTimeout(function(){b.classList.add('go')},2600);
})();

// Cycle through the role labels with a type-and-delete effect.
(function(){
  var rt=document.getElementById('rt'),ws=['Developer','Django Builder','AI/ML Learner'],wi=0,ci=ws[0].length,del=true;
  function tick(){
    if(del){ci--;rt.textContent=ws[wi].slice(0,ci);if(ci<=0){del=false;wi=(wi+1)%ws.length}setTimeout(tick,55)}
    else{ci++;rt.textContent=ws[wi].slice(0,ci);if(ci>=ws[wi].length){del=true;setTimeout(tick,1800);return}setTimeout(tick,85)}
  }
  setTimeout(tick,4500);
})();

// Duplicate the skills list so the marquee loops seamlessly.
(function(){
  var l=['Python','Django','REST APIs','React','SQL','OpenCV','Machine learning','Git'],h='';
  for(var r=0;r<2;r++)l.forEach(function(t){h+='<span>'+t+'</span>'});
  document.getElementById('mqt').innerHTML=h+h;
})();

// Follow the pointer with a soft glow and update the scroll progress bar.
(function(){
  var g=document.getElementById('glow'),bar=document.getElementById('bar'),gx=innerWidth/2,gy=innerHeight/2,tx=gx,ty=gy;
  addEventListener('pointermove',function(e){tx=e.clientX;ty=e.clientY});
  (function gl(){gx+=(tx-gx)*.12;gy+=(ty-gy)*.12;g.style.transform='translate('+(gx-250)+'px,'+(gy-250)+'px)';requestAnimationFrame(gl)})();
  addEventListener('scroll',function(){var m=document.documentElement.scrollHeight-innerHeight;bar.style.transform='scaleX('+(m>0?scrollY/m:0)+')'},{passive:true});
})();

// Reveal content as it enters the viewport, with a small stagger.
(function(){
  var rio=new IntersectionObserver(function(es){es.forEach(function(e){
    if(e.isIntersecting){var t=e.target;t.classList.add('in');rio.unobserve(t);setTimeout(function(){t.style.transitionDelay=''},1200)}
  })},{threshold:.12});
  document.querySelectorAll('h2,.about p,.facts div,.row,.proj,.stack span,.certs li,.card,.aic div,.ai>*').forEach(function(e){
    e.classList.add('rv');e.style.transitionDelay=(Array.prototype.indexOf.call(e.parentNode.children,e)%6*70)+'ms';rio.observe(e);
  });
})();

// Count the profile stats up when they first become visible.
document.querySelectorAll('.facts b').forEach(function(b){
  var t=b.textContent,v=parseFloat(t.replace(/,/g,'')),dec=(t.split('.')[1]||'').replace(/\D/g,'').length,suf=t.replace(/[\d.,]/g,''),ran=false;
  b.textContent='0'+suf;
  new IntersectionObserver(function(es,o){
    if(es[0].isIntersecting&&!ran){ran=true;o.disconnect();var s=performance.now();
      (function f(n){var p=Math.min((n-s)/1600,1),val=v*(1-Math.pow(1-p,3));b.textContent=(dec?val.toFixed(dec):Math.round(val).toLocaleString('en-US'))+suf;if(p<1)requestAnimationFrame(f)})(s);
    }
  }).observe(b);
});

// Add a subtle pointer tilt to the project previews.
document.querySelectorAll('.shot').forEach(function(s){
  s.addEventListener('pointermove',function(e){var r=s.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;s.style.transform='perspective(800px) rotateY('+x*10+'deg) rotateX('+(-y*10)+'deg)'});
  s.addEventListener('pointerleave',function(){s.style.transform=''});
});

// Wire up the before-and-after sliders and image selection tabs.
document.querySelectorAll('.cmp').forEach(function(f){
  var r=f.querySelector('input');
  f._set=function(v){r.value=v;f.style.setProperty('--p',v+'%')};
  r.addEventListener('input',function(){f._set(r.value)});
});
document.querySelectorAll('.tabs button').forEach(function(b,i){
  b.addEventListener('click',function(){
    document.querySelectorAll('.tabs button').forEach(function(x){x.classList.toggle('on',x===b);x.setAttribute('aria-pressed',String(x===b))});
    document.querySelectorAll('.cmp').forEach(function(f,j){f.hidden=j!==i});
  });
});
(function(){
  var cw=document.querySelector('.cmpwrap');
  new IntersectionObserver(function(es,o){
    if(!es[0].isIntersecting)return;o.disconnect();
    var f=cw.querySelector('.cmp'),s=performance.now();
    (function a(n){var p=Math.min((n-s)/2400,1);f._set(50+40*Math.sin(p*Math.PI*2));if(p<1)requestAnimationFrame(a);else f._set(50)})(s);
  },{threshold:.5}).observe(cw);
})();

// Animate signal pulses moving through the neural-network diagram.
(function(){
  var c=document.getElementById('nn'),x=c.getContext('2d'),L=[3,5,5,2],N=[],E=[],Pu=[],W,H,d=Math.min(devicePixelRatio||1,2),f=0;
  function sz(){W=c.clientWidth;H=c.clientHeight;c.width=W*d;c.height=H*d;x.setTransform(d,0,0,d,0,0);N=[];E=[];
    L.forEach(function(n,i){var col=[];for(var j=0;j<n;j++)col.push({x:W*(.12+.76*i/(L.length-1)),y:H*((j+1)/(n+1)),g:0,l:i});N.push(col)});
    for(var i=0;i<N.length-1;i++)N[i].forEach(function(a){N[i+1].forEach(function(b){E.push({a:a,b:b})})});Pu=[]}
  sz();addEventListener('resize',sz);
  (function loop(){
    x.clearRect(0,0,W,H);f++;
    if(f%35===0&&Pu.length<60){var s=E.filter(function(e){return e.a.l===0});Pu.push({e:s[Math.random()*s.length|0],t:0})}
    x.lineWidth=1;x.strokeStyle='rgba(180,190,210,.13)';
    E.forEach(function(e){x.beginPath();x.moveTo(e.a.x,e.a.y);x.lineTo(e.b.x,e.b.y);x.stroke()});
    for(var i=Pu.length-1;i>=0;i--){var p=Pu[i];p.t+=.02;
      var px=p.e.a.x+(p.e.b.x-p.e.a.x)*p.t,py=p.e.a.y+(p.e.b.y-p.e.a.y)*p.t;
      x.fillStyle='#7fe3b0';x.beginPath();x.arc(px,py,2.5,0,6.283);x.fill();
      if(p.t>=1){p.e.b.g=1;Pu.splice(i,1);
        if(p.e.b.l<L.length-1){var nx=E.filter(function(e){return e.a===p.e.b});for(var k=0;k<2;k++)Pu.push({e:nx[Math.random()*nx.length|0],t:0})}}}
    N.forEach(function(col){col.forEach(function(n){
      x.fillStyle='rgba(127,227,176,'+(.25+n.g*.75)+')';x.beginPath();x.arc(n.x,n.y,6+n.g*4,0,6.283);x.fill();n.g*=.94})});
    requestAnimationFrame(loop);
  })();
})();
